import logging
import re
import time

from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import AttenuationReadError
from taf.hw.rf_attenuator.utils.telnet import TelnetClient


class Eubus(Attenuator):
    DB_REGEX = r'Ch([1-9][0-9]?):([0-9]\d*\.\d+)'
    PORT_NOT_EXIST_REGEX = r'Impossible channel'
    MAX_SUPPORTED_ATTENUATION = 95.5
    MIN_SUPPORTED_ATTENUATION = 0

    def __init__(self, ip, port=23, min_attenuation=None, max_attenuation=None):
        super(Eubus, self).__init__()
        self.ip = ip
        self.port = port
        self.conn = None
        self.telnet = TelnetClient()
        self.is_connected = False
        self.min_attenuation = self._validate_min_attenuation(min_attenuation, self.MIN_SUPPORTED_ATTENUATION)
        self.max_attenuation = self._validate_max_attenuation(max_attenuation, self.MAX_SUPPORTED_ATTENUATION)

    def connect(self, **kwargs):
        """
        Derived should put here code required to establish connection with attenuation controller
        allowing to change attenuation on specific RF-port of that device
        """
        if not self.is_connected:
            self.telnet.connect(self.ip, self.port)
            self.is_connected = True
            logging.info('Connection to Eubus rf_attenuator established!')
            result = self.telnet.write_and_read(command='\r\n', read_method='until', read_flag="#")
            logging.debug("Catched banner message: {}".format(result))
        else:
            logging.warning('Eubus rf_attenuator already connected.')

    def disconnect(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if self.is_connected:
            self.telnet.close_connection()
            self.is_connected = False
        else:
            logging.warning('Connection to Eubus is not established.')

    def _set_single_port_decibel_attenuation(self, port, attenuation_value_db):
        """
        Set attenuation for single RF-port inside rf_attenuator device.
        It should be implemented by specific rf_attenuator impl.
        :param port: identification of rf-port specific for given rf_attenuator HW, f.ex. pins number
        :param attenuation_value_db: float or int in db
        """

        attenuation_value_db = round(attenuation_value_db * 2) / 2
        set_attenuation_cmd = 'db {} {}'.format(attenuation_value_db, port)
        self.telnet.write_command(set_attenuation_cmd)
        logging.info('Port {} value set to {} dB.'.format(port, attenuation_value_db))

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        set_command = "db"
        for port, value in zip(rf_port_addresses, attenuation_values_db):
            atten_and_port = ' {} {}'.format(value, port)
            set_command += atten_and_port
        self.telnet.write_command(set_command)

    def read_port_attenuation(self, port):
        """read attenuation value in db for port"""
        read_port_cmd = 'db ? {}'.format(port)
        time.sleep(1)  # timeout for telnet buffer to clear
        att_output = self.telnet.write_and_read(read_port_cmd, read_method='until', read_flag='#')
        re_out = re.search(self.DB_REGEX, att_output)
        if re_out:
            attenuator_channel = re_out.group(1)
            value_in_db = re_out.group(2)
            logging.debug("Attenuation port {} has value {}dB".format(attenuator_channel, value_in_db))
        elif re.search(self.PORT_NOT_EXIST_REGEX, att_output):
            raise AttenuationReadError("Tried to read attenuation of port {}. Such port does not exist".format(port))
        else:
            raise AttenuationReadError("Could not read attenuation value for port: {}.".format(port))
        return float(value_in_db)
